fields.Story Bible:
{
  "logline": "A 60-second documentary story bible showing how imperial Rome fed a city often estimated at about one million people: grain gathered from Mediterranean provinces, landed at Ostia and Portus, measured by mensores, stored in horrea, moved up the Tiber, and rationed under the annona without inventing numbers the evidence cannot fix.",
  "characters": [
    {
      "name": "praefectus annonae",
      "role": "Imperial official embodying state oversight of Rome’s grain supply under the annona",
      "visual_description": "A clean-shaven Roman man in his late 40s with olive skin, a lean build, deep-set dark brown eyes, a long straight nose, and short black hair combed forward in tight waves. He wears a full-length off-white wool toga with a narrow dark purple stripe over a knee-length natural-linen tunic with short sleeves, a brown leather belt hidden beneath the drape, and dark brown strapped leather calcei shoes. He carries a folded wax tablet and a short boxwood stylus in his left hand, and a bronze signet ring is visible on his right hand."
    },
    {
      "name": "mensor",
      "role": "State measurer checking grain quantity and quality on ship, quay, and warehouse floor",
      "visual_description": "A Roman man in his mid 30s with sun-browned skin, a compact muscular build, curly dark hair cropped close, a square jaw, and a short trimmed beard. He wears a knee-length undyed beige wool tunic with narrow short sleeves, a dark reddish-brown sleeveless hoodless work cloak pinned on the right shoulder with a small bronze fibula, a plain rope belt, and dusty calf-high brown leather work boots with cross-laced fronts. He carries a wooden measuring rod, a shallow bronze grain scoop, and a wax tablet hanging from a leather thong at his waist."
    },
    {
      "name": "river barge hauler",
      "role": "Laborer representing the human effort that moved food inland from the sea harbors to Rome",
      "visual_description": "A Roman man in his early 40s with weathered tan skin, a broad back, heavy forearms, close-cropped dark hair, and a broken nose. He wears a sleeveless faded blue-grey knee-length tunic of coarse wool, belted with a wide cracked brown leather belt, a short hoodless dark brown wool cape hanging open and tied with two cords at the chest, and thick rawhide sandals wrapped high around the ankles. He has a frayed tow rope over one shoulder and chaff dust on his shins and hands."
    }
  ],
  "objects": [
    {
      "name": "grain transport sack",
      "visual_description": "A large cylindrical sack of coarse tan woven hemp, packed full so the sides bow outward, tied at the neck with doubled flax cord, with a black painted stencil reading ANN in block Roman letters and a small red sealing dab near the knot; the fabric is abraded at the base and dusted with pale grain flour."
    },
    {
      "name": "olive-oil amphora",
      "visual_description": "A tall narrow Roman Dressel 20 amphora in orange-brown fired clay with a rounded belly, thick rolled rim, two loop handles from shoulder to neck, and a pointed stub base; one shoulder bears black painted tituli, the lower body is streaked with white mineral crust and shipping grime, and one side has a chipped patch exposing lighter clay beneath."
    },
    {
      "name": "river grain barge",
      "visual_description": "A low, broad-beamed wooden river barge with a blunt bow, tar-darkened hull planks, a single short mast lowered flat on deck, bundled tan sailcloth, stacked grain sacks under rough beige canvas covers, and a heavy towline fixed to an iron bow ring; the gunwales are rubbed pale from repeated loading."
    }
  ],
  "locations": [
    {
      "name": "Mediterranean grain convoy — open sea approach",
      "visual_description": "A wide expanse of dark blue-green sea under a pale horizon, with one deep-bellied Roman merchant grain ship at center angled toward camera, cream square sail half-filled by wind, reddish-brown hull riding low with cargo. To the left, two smaller sail silhouettes trail farther back; to the right, empty water with gulls skimming the surface. In the background, only haze and sky are visible, stressing distance from Rome and the long maritime supply line from Sardinia, Sicily, Africa, and Egypt."
    },
    {
      "name": "Ostia river port — late Republic and early Imperial unloading zone",
      "visual_description": "A busy rectangular riverfront work zone beside the Tiber with a broad stone quay running horizontally across the frame, cargo boats moored at center, stacked grain sacks and handcarts on the left, and low storage buildings of tan brick and timber on the right. In the background, a flat riverside skyline of tiled roofs, cranes, and masts rises behind the quay. The ground is hard-packed dirt mixed with stone paving, and the space reads as the designated public area for unloading, transporting, and storing grain at Ostia before the later harbor expansions."
    },
    {
      "name": "Portus — Claudian harbor basin",
      "visual_description": "A vast engineered harbor about 3 km north of the Tiber mouth, with open protected water at center enclosed by long stone moles, a lighthouse structure visible on one breakwater in the mid-background, and canal mouths leading inland. On the left stand moored seagoing freighters with furled cream sails; on the right, quays crowded with carts, dockworkers, and stacked cargo. Compared with Ostia, this state adds larger protected anchorage, heavier maritime infrastructure, and a clearer artificial geometry built for overflow traffic."
    },
    {
      "name": "Portus — Trajanic hexagonal basin",
      "visual_description": "A monumental hexagonal harbor basin seen from an elevated angle, its six straight stone-edged sides enclosing calm green water at center, with ordered quays and warehouses tracing the geometric perimeter. On the left, narrow service roads and brick store buildings run in crisp lines; on the right, moored cargo vessels sit neatly against the basin walls. In the background, canals and low administrative buildings connect the harbor to the wider port complex. Compared with the Claudian basin, this state adds the unmistakable hexagonal form and a denser, more rationalized storage-and-transfer landscape."
    },
    {
      "name": "Grandi Horrea, Ostia — grain warehouse interior",
      "visual_description": "A long brick warehouse corridor opening into storage cellae, with massive red-brown brick walls and square doorways repeating in perspective, raised floors on short brick suspensurae visible beneath timber planking in the foreground, and conical heaps of loose grain and hemp sacks arranged in bays at center. On the left, narrow high windows admit thin daylight; on the right, measuring tables, baskets, and tally marks sit beside door lintels. The background fades into shadowed arches, emphasizing dry storage technology built to protect grain from damp."
    },
    {
      "name": "Tiber towpath and river approach to Rome",
      "visual_description": "A muddy towpath runs diagonally along the left edge of the Tiber while a loaded low barge occupies the center of the river, its towline stretched taut to men or animals just out of frame. On the right bank stand reeds, mooring posts, and occasional stone embankments; in the background, the river bends toward a hazy urban silhouette of warehouses, temple roofs, and smoke. The space is narrower and more inland than the sea harbors, showing the second transport stage after unloading and storage."
    },
    {
      "name": "Testaccio plain by the Emporium — Horrea Galbana and Monte Testaccio",
      "visual_description": "A broad working district south of central Rome with a river landing in the foreground, long warehouse blocks of brick and tile at center-left, and the rising mound of Monte Testaccio at center-right built from broken orange amphora sherds. Cart tracks cut through dusty ground; intact oil amphorae stand in clusters near the warehouse doors. In the background, more storage buildings and a muted urban ridge close the horizon. The place is identified by the combination of river port, major horrea, and the artificial hill of discarded olive-oil containers."
    },
    {
      "name": "Rome grain distribution courtyard",
      "visual_description": "An enclosed stone-paved courtyard in the city with a colonnade at the back, a chest-high distribution counter at center, and orderly lines marked by low wooden rails. On the left, recipients wait with cloth sacks and baskets; on the right, officials sit at a narrow table with wax tablets and scales. In the background, plastered walls in worn ochre and cream rise above the crowd, with a single arched entry controlling access. The geometry is tight and administrative, contrasting with the open harbor spaces and emphasizing rationed urban distribution."
    }
  ],
  "era_setting": "Ancient Rome during the early to high Imperial period, centered on the annona system from Augustus through the mature harbor infrastructure of Claudius and Trajan, with documentary treatment that distinguishes secure facts from estimates and leaves unknown quantities unstated.",
  "visual_style": {
    "palette": "travertine white, brick red, Nile silt beige, oxidized bronze green, Tiber mud brown",
    "lighting": "Chapter progression must change every scene: chapter 1 hard noon glare with marine haze on the open sea; chapter 2 bright dry afternoon light on the Ostia quay; chapter 3 overcast silver light across the Claudian harbor; chapter 4 dawn haze with low sidelight over Trajan’s hexagonal basin; chapter 5 dim warehouse daylight with narrow window shafts inside the Grandi Horrea; chapter 6 late golden afternoon on the Tiber towpath; chapter 7 dusk with cooling sky and warm reflected light at Testaccio; chapter 8 lamplit interior evening in the grain distribution courtyard.",
    "camera": "35mm and 50mm documentary framing, mostly eye-level observational compositions, locked-off wides for geography, restrained handheld for labor details, slow lateral tracking only when following sacks, amphorae, or barges; no heroic low angles, no sweeping fantasy crane moves, no anachronistic aerial spectacle except a sober elevated overview for Trajan’s hexagonal basin.",
    "film_look": "Restrained archival-documentary texture with fine natural grain, softened contrast, dusty atmosphere, sun-faded mineral colors, subtle gate-weave feel, and period-correct surface wear on skin, cloth, wood, brick, and clay."
  },
  "motifs": [
    "grain measured before it is trusted",
    "water-to-warehouse-to-river chain of supply",
    "state oversight recorded on wax tablets",
    "storage architecture as survival technology",
    "olive oil visible beside grain as parallel bulk provisioning",
    "scarcity implied by limited reserves rather than dramatized invention"
  ],
  "continuity_rules": [
    "Keep all visuals strictly inside the real food-supply system of imperial Rome; no invented battles, riots, speeches, or unnamed miracles.",
    "Use only the three recurring human figures listed here, with exactly the same face, age, hair, clothing, and props in every appearance.",
    "Show grain logistics in the correct chain: sea convoy, unloading, harbor transfer, measurement, warehouse storage, Tiber transport, urban storage and distribution.",
    "Portus — Claudian harbor basin appears before Portus — Trajanic hexagonal basin; the hexagonal basin appears only in later chapters after the Claudian state is established.",
    "Do not state exact annual tonnage, population, provincial shares, or recipient totals as certain when the evidence is disputed; if text appears in-scene, it must frame them as estimates.",
    "Keep architecture, ships, tools, sacks, amphorae, and writing materials rigorously ancient Roman and non-anachronistic.",
    "Consecutive chapters must never share the same hour, weather, or lighting condition.",
    "Treat documents, buildings, vessels, and stored goods as evidence: observational, specific, and unsensational."
  ]
}
